#!/usr/bin/env python3
"""Print the installed pi package root, or nothing.

An absent pi is a supported state (CI), so this always exits 0 and the caller
switches arms on an empty stdout.

Finding it is fiddly enough to deserve its own file: `pi` on the PATH can be a
symlink straight to dist/bundle/cli.js, or an npm/pnpm shim script whose exec
lines build the path from a $basedir variable, so the package path is not
absolute as written. The trailing `# cmd-shim-target=` comment is absolute but
only npm writes it. Try every shape and keep the first that is a real package.
"""

import os
import re
import shutil
import sys
from pathlib import Path

PACKAGE = "@earendil-works/pi-coding-agent"
# A path fragment reaching the package, possibly prefixed by the shim's $basedir.
FRAGMENT = re.compile(r"((?:\$\{?basedir\}?|/)[^\s\"']*" + re.escape(PACKAGE) + r")")


def is_package_root(path: Path) -> bool:
    return (path / "dist" / "core").is_dir()


def candidates(binary: Path):
    real = Path(os.path.realpath(binary))
    basedir = real.parent

    # A symlink to .../pi-coding-agent/dist/bundle/cli.js
    for parent in real.parents:
        if parent.name == PACKAGE.split("/")[-1]:
            yield parent

    try:
        text = real.read_text(errors="replace")
    except OSError:
        return

    for match in FRAGMENT.finditer(text):
        raw = match.group(1)
        if raw.startswith("$"):
            raw = re.sub(r"^\$\{?basedir\}?", str(basedir), raw)
        yield Path(raw)


def main() -> None:
    override = os.environ.get("PI_PACKAGE_ROOT")
    if override:
        if is_package_root(Path(override)):
            print(override, end="")
        return

    binary = shutil.which("pi")
    if not binary:
        return

    for candidate in candidates(Path(binary)):
        if is_package_root(candidate):
            print(candidate, end="")
            return


if __name__ == "__main__":
    main()
    sys.exit(0)
